const $=s=>document.querySelector(s);
const source={geo:'https://en.wikipedia.org/wiki/Swat_Valley',river:'https://en.wikipedia.org/wiki/Swat_River',heritage:'https://whc.unesco.org/en/tentativelists/7034/',voices:'https://folklife.si.edu/magazine/stream-of-voices-torwali-language-music-poetry-pakistan',gawri:'https://en.wikipedia.org/wiki/Gawri_language',craft:'https://kparchaeology.gkp.pk/swat-museum/',environment:'https://nhess.copernicus.org/articles/25/1071/2025/index.html',flood:'https://www.eda.admin.ch/content/dam/countries/countries-content/pakistan/en/synthesis-report-floods-report_en.pdf'};
const photos=[{id:'lake',title:'Mahodand Lake-Summer 2015.jpg',author:'Murtaza Mahmud',license:'4.0',date:'2015',alt:'Mountain, pine forest and still water at Mahodand Lake in summer'},{id:'mahodand',title:'Mahodand Lake, Kalam, Swat, Pakistan.jpg',author:'Abeermajid1996',license:'4.0',date:'2018',alt:'Wildflowers and meadow beside Mahodand Lake, with wooded slopes and mountains beyond'},{id:'kalam',title:'Kalam Valley Mountain.jpg',author:'نوید بٹ',license:'4.0',date:'2017',alt:'Mountain landscape in Kalam Valley, Swat'},{id:'butkara',title:'General View of the main Butkara-I Stupa.JPG',author:'Muhammad Zahir',license:'3.0',date:'2013',alt:'The excavated circular stone foundations of Butkara I stupa in Swat'}];
const photo=(id,cls='')=>{const p=photos.find(p=>p.id===id);return `<img class="${cls}" src="assets/${id}.jpg" alt="${p.alt}" ${cls==='place-cover'?'':'loading="lazy"'}>`};
const round=(url,text)=>`<a class="round-link" href="${url}">${text}<i aria-hidden="true">↗</i></a>`;
const read=(url,text='Read the source')=>`<a class="article-link" href="${url}" target="_blank" rel="noopener">${text} ↗</a>`;
const places=[
{id:'mahodand',name:'Mahodand',region:'Upper valley · Alpine lake',image:'mahodand',x:400,y:65,land:'Above the forests of upper Swat, Mahodand brings mountain water, meadow and high ridges into one frame. Its setting belongs to the Ushu side of the valley.',voice:'A lake is not an empty landscape. Upper Swat is part of a lived mountain region, including Gawri-speaking communities around Kalam, Ushu and Utror.',memory:'The photograph is a record of a particular moment: wildflowers beside the lake in 2018. It is not evidence of present road, water or visitor conditions.'},
{id:'kalam',name:'Kalam',region:'Upper valley · River confluence',image:'kalam',x:290,y:155,land:'At Kalam, the Ushu and Utror rivers meet. From here the Swat River runs south, connecting mountain forests with the settlements downstream.',voice:'Gawri, also called Kalami, is spoken around Kalam, Ushu and Utror. Its sounds, tones and oral traditions form part of the valley’s living cultural landscape.',memory:'Water connects Kalam to the lower valley. The 2010 and 2022 floods also show how closely the lives of upstream and downstream communities are linked.'},
{id:'bahrain',name:'Bahrain',region:'Middle valley · River town',x:335,y:275,land:'South of Kalam, Bahrain sits beside the Swat River. Here, the valley’s riverside settlements make the connection between geography and everyday life visible.',voice:'Bahrain is a centre of Torwali language and cultural life. Community-led work documents poetry and song and supports children learning their mother tongue.',memory:'The 2010 floods form part of the recent history recalled by Torwali cultural organisers. Their response included a festival celebrating language, music and identity.'},
{id:'madyan',name:'Madyan',region:'Middle valley · Riverside settlement',x:285,y:355,land:'Madyan lies downstream of Bahrain, along the corridor of the Swat River. The atlas places it between the upper valleys and the wider lower valley.',voice:'The wider valley includes Pashto, Torwali, Gawri and Gujari speakers. Language boundaries are not hard borders; no single language represents every resident.',memory:'Riverside towns belong to an evolving landscape. Understanding settlement here means paying attention to both the river channel and the land around it.'},
{id:'mingora',name:'Mingora',region:'Lower valley · Urban centre',x:235,y:465,land:'Mingora is the main urban centre of Swat. Nearby Saidu Sharif connects the contemporary townscape with the museum and archaeological sites of the lower valley.',voice:'The busy lower valley is part of Swat’s Pashto-speaking cultural landscape. The region’s identities also extend beyond a single town, language or community.',memory:'Near Mingora and Saidu Sharif, Butkara I preserves the remains of a Buddhist sacred complex. Its stone structures offer another way to read the valley.'},
{id:'barikot',name:'Barikot',region:'Lower valley · Archaeological landscape',x:135,y:550,land:'Barikot occupies a hill and adjacent plain beside the Swat River. The relationship between hill, settlement and water is central to reading this landscape.',voice:'Barikot is a present-day place as well as an archaeological site. Its history should not turn the surrounding living community into a backdrop.',memory:'Excavations at ancient Bazira reveal successive urban and sacred spaces. UNESCO’s 2026 Tentative List entry describes a long, layered history; this is not an inscribed World Heritage Site.'}
];
const sidePlaces={ 'malam-jabba':{name:'Malam Jabba',region:'Eastern side valley · Mountain slopes',land:'Malam Jabba lies east of the main Swat River corridor. Its mountain setting belongs to a side valley, so it does not appear as a stop on the river itself.',voice:'Tourism is one part of a lived landscape. A useful account must also make room for residents, work and changing land use.',memory:'The atlas distinguishes this eastern mountain destination from the main north–south river route.'}};
function riverSVG(interactive=false){let contours='';for(let n=0;n<14;n++){const k=n*17;contours+=`<path class="contour" d="M${70-k},-10 C${290-k},120 ${15+k},200 ${170+k},315 S${440-k},420 ${70+k},640"/><path class="contour" d="M${550+k},-10 C${350+k},150 ${620-k},200 ${460-k},340 S${280+k},490 ${580-k},660"/>`;}return `<svg viewBox="0 0 600 640" role="img" aria-label="Schematic of the Swat River corridor, north at top. Not a navigation map.">${contours}<path class="tributary" d="M160 50 Q220 115 290 155 M400 65 Q410 110 290 155"/><path class="river-line" d="M290 155 C220 200 390 225 335 275 S350 330 285 355 S310 425 235 465 S220 515 135 550 L105 610"/>${places.map((p,i)=>`<g class="map-node ${i===selected?'active':''}" data-place="${i}" ${interactive?`tabindex="0" role="button" aria-label="Explore ${p.name}"`:''}><circle cx="${p.x}" cy="${p.y}" r="6"/><text x="${p.x+18}" y="${p.y+5}">${p.name}</text></g>`).join('')}<text x="405" y="450" fill="#94ac91" font-size="10" letter-spacing="3" transform="rotate(-65 405 450)">SWAT VALLEY</text></svg>`}
let selected=1,lens='land';
function home(){return `<div class="hero-meta"><span>Pakistan / Khyber Pakhtunkhwa</span><span>A field guide to landscape, memory & life</span><span>35° N · 72° E / Region</span></div><section class="hero"><img src="assets/lake.jpg" alt="${photos[0].alt}" fetchpriority="high"><h1>SWAT</h1><span class="urdu" lang="ur">سوات</span><div class="hero-bottom"><h2>A valley,<br>in many currents.</h2><div><p>Follow a river through mountains,<br>living languages and deep time.</p>${round('#/atlas','Enter the valley')}</div></div></section><div class="hero-caption"><span>Mahodand Lake, upper Swat · Photograph by Murtaza Mahmud</span><a href="#/sources">Image credits ↗</a><span>Scroll to look closer ↓</span></div><section class="intro"><div class="aside"><span class="eyebrow">Beyond the postcard</span><svg viewBox="0 0 100 160" aria-hidden="true"><path d="M70 0 C0 30 100 45 45 75 S95 115 25 160 M85 0 C15 30 115 45 60 75 S110 115 40 160" fill="none" stroke="#708267" stroke-width="1"/></svg></div><div><h2>Mountains hold the valley.<br>The river holds it together.</h2><p>In northern Pakistan, the Swat River threads a landscape of forests, alpine lakes, cultivated land and busy towns. Along its banks, different histories and ways of life meet.</p><p>Look past a single view. There are stones to read, languages to hear about, and a landscape still being shaped by water and the people who call it home.</p><a class="underlink" href="#/atlas">Find your way through Swat ↗</a></div></section><section class="atlas-tease"><div><span class="eyebrow">An atlas of connections</span><h2>Let the river<br>be your guide.</h2><p>Move from the high valleys toward the plains. Change the lens to discover what the same place can tell you about land, language and memory.</p>${round('#/atlas','Follow the current')}</div><div class="river-preview">${riverSVG()}<a href="#/place/kalam" style="left:15%;top:14%">Kalam ↗</a><a href="#/place/bahrain" style="right:0;top:45%">Bahrain ↗</a><a href="#/place/barikot" style="left:0;bottom:15%">Barikot ↗</a><span class="caption map-caption">River corridor · Schematic, not to scale</span></div></section><section class="stories"><div class="section-head"><div><span class="eyebrow">Ways of seeing</span><h2>More than a landscape.</h2></div><span class="eyebrow">Two threads to follow</span></div><div class="story-grid"><a class="story-link" href="#/heritage"><div class="story-image">${photo('butkara')}</div><p class="eyebrow">Stone / Sacred spaces / Archaeology</p><h3>The valley beneath<br>the valley. ↗</h3><p>At Butkara and Barikot, fragments of older worlds remain part of the present landscape.</p></a><a class="story-link" href="#/voices"><div class="culture-block"><div class="words" lang="ur">پښتو &nbsp; توروالی<br>گاؤری &nbsp; گوجری</div><span class="tiny">PASHTO · TORWALI · GAWRI · GUJARI</span></div><p class="eyebrow">Language / Poetry / Belonging</p><h3>A place has<br>many voices. ↗</h3><p>Swat is not one story told in one language. Meet the people working to keep its traditions in use.</p></a></div></section><section class="environment-tease"><div><span class="eyebrow">A living, changing landscape</span><h2>The river needs room.</h2><p>Floods, settlement and changing land cover are part of the same story. Beauty is only the beginning of understanding a place.</p></div>${round('#/changing','Read the landscape')}</section>`}
function atlas(){return `<section class="dark"><div class="atlas-head"><div><span class="eyebrow">The river atlas</span><h1>Follow the current.</h1></div><p>Choose a place on the river.<br>Change the lens. See what connects.</p></div><div class="atlas-layout"><div class="map">${riverSVG(true)}<span class="map-north">N<br>↑</span><span class="map-key">Schematic river corridor<br>North → south · Not for navigation</span></div><aside class="atlas-panel"><div class="lens-tabs" aria-label="Story lens">${[['land','Landscape'],['voice','Language'],['memory','Memory']].map(([k,n])=>`<button data-lens="${k}" aria-pressed="${lens===k}">${n}</button>`).join('')}</div><div id="atlas-story" aria-live="polite"></div><div class="atlas-controls"><button id="upstream" aria-label="Previous place upstream">↑</button><input type="range" min="0" max="5" step="1" value="${selected}" aria-label="Move along the river"><button id="downstream" aria-label="Next place downstream">↓</button></div><p class="caption">Move along the river · Arrow keys also work on the slider.</p></aside></div></section><section class="atlas-sidenote"><span class="eyebrow">Beyond the main current</span><p>Not every place lies beside the river. Malam Jabba occupies an eastern side valley; Mahodand sits in the upper catchment. This is a guide to relationships, not a road map.</p><div class="place-list">${[...places,...Object.entries(sidePlaces).map(([id,p])=>({...p,id}))].map(p=>`<a href="#/place/${p.id}">${p.name} ↗</a>`).join('')}</div></section>`}
function updateAtlas(){let p=places[selected];$('#atlas-story').innerHTML=`${p.image?photo(p.image,'place-cover'):`<div class="photo-placeholder" aria-hidden="true">${p.name}</div>`}<div class="place-number">${p.region}</div><h2>${p.name}</h2><p>${p[lens]}</p><a class="underlink" href="#/place/${p.id}">Open the place notes ↗</a>`;document.querySelectorAll('.map-node').forEach((el,i)=>el.classList.toggle('active',i===selected));$('.atlas-controls input').value=selected;$('.atlas-controls input').setAttribute('aria-valuetext',p.name);$('#upstream').disabled=selected===0;$('#downstream').disabled=selected===5;document.querySelectorAll('[data-lens]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.lens===lens))}
function heritage(){return `<section class="heritage-hero"><div class="page-title"><a class="back" href="#/">← BACK TO THE VALLEY</a><p class="eyebrow" style="margin-top:60px">Deep time / The lower valley</p><h1>The stones<br>are still<br>speaking.</h1><p class="deck">A sacred complex. An ancient town.<br>Many lives laid over the same ground.</p></div><figure>${photo('butkara')}<figcaption>Butkara I · Muhammad Zahir · 2013 / CC BY-SA 3.0</figcaption></figure></section><section class="essay"><div class="eyebrow">Reading a layered landscape<br>Butkara · Barikot · Saidu Sharif</div><div><h2>History is not a single horizon.</h2><p>The archaeological landscapes of Swat hold traces of settlement, worship and exchange. The stone remains at Butkara I belong to a Buddhist sacred complex near Saidu Sharif. Further down the valley, Barikot reveals layers of an ancient urban life.</p><p>These places are connected to the wider Gandharan world, but their stories are local too: the position of a hill, the meeting of paths, a river beside a settlement.</p>${read(source.heritage,'Explore the Bazira–Barikot record')}<div class="timeline"><span class="eyebrow">Open a layer</span>${[['An inhabited landscape','Before the monumental remains, there were already people living and working here. The Bazira–Barikot record describes evidence reaching back into the second millennium BCE. Archaeology follows these layers through material evidence, not a single founding legend.'],['An urban and sacred landscape','Barikot’s excavated spaces include streets, workshops, defensive works and Buddhist sacred areas. Successive building phases reveal how a place was altered and reused.'],['A landscape in the present','The archaeological sites sit within a living valley. Conservation, research and surrounding communities all belong to their future. Bazira–Barikot appears on Pakistan’s UNESCO Tentative List as of May 2026; tentative listing is not World Heritage inscription.']].map(([t,p],i)=>`<button class="layer-toggle" aria-expanded="${i===0}" aria-controls="layer-${i}"><strong>${t}</strong><span>${i===0?'−':'+'}</span></button><article id="layer-${i}" ${i===0?'':'hidden'}>${p}</article>`).join('')}</div></div></section><section class="environment-tease"><div><span class="eyebrow">Return to geography</span><h2>Put the past in place.</h2><p>Find Barikot on the river and switch to the memory lens.</p></div>${round('#/atlas','Open the river atlas')}</section>`}
function voices(){return `<div class="page-title"><span class="eyebrow">Living culture / Language & belonging</span><h1>A valley of voices.</h1><p class="deck">A landscape is also carried in names, poems, songs and the words people use at home.</p></div><div class="voice-display" aria-label="Pashto, Torwali, Gawri and Gujari"><span lang="ps">پښتو</span><span lang="trw">توروالی</span><span lang="gwc">گاؤری</span><span lang="gju">گوجری</span></div><section class="essay"><div class="eyebrow">Languages are lived<br>Not museum objects</div><div><h2>No single voice<br>stands for everyone.</h2><p>Pashto, Torwali, Gawri and Gujari are among the languages spoken in Swat. Their communities overlap with a geography of towns, side valleys and mountain settlements. These brief notes are a starting point, not a complete cultural portrait.</p><div class="language-row"><h3>Torwali</h3><div><p>Around Bahrain and neighbouring valleys, Torwali language, music and poetry remain closely connected. Cultural organiser Zubair Torwali describes community-led festivals, documentation and education as part of keeping that inheritance alive.</p>${read(source.voices,'Read Zubair Torwali at Smithsonian Folklife')}</div></div><div class="language-row"><h3>Gawri</h3><div><p>Also known as Kalami, Gawri is spoken around Kalam, Ushu and Utror, as well as in parts of Upper Dir. Its tonal system and oral traditions deserve attention on their own terms.</p>${read(source.gawri,'Explore the language references')}</div></div><div class="language-row"><h3>Making & memory</h3><div><p>Swat’s crafts include embroidered textiles and woodwork. Objects carry knowledge through use and making. A fuller account should come from named makers, with their permission and their own descriptions of the work.</p>${read(source.craft,'Explore the Swat Museum collections')}</div></div></div></section><section class="environment-tease"><div><h2>Language has a geography.</h2><p>Follow the river with the language lens.</p></div>${round('#/atlas','Explore the connections')}</section>`}
function changing(){return `<div class="page-title"><span class="eyebrow">Water / Land / Change</span><h1>The river<br>needs room.</h1><p class="deck">A photograph can hold a moment still.<br>A river never stays in one moment.</p></div><figure class="full-photo">${photo('kalam')}<figcaption class="caption">Kalam Valley · نوید بٹ · 2017. A landscape photograph, not an image of a flood.</figcaption></figure><section class="essay"><div class="eyebrow">Seeing beyond the view</div><div><h2>Beauty and vulnerability<br>share the same ground.</h2><p>The 2010 and 2022 floods transformed lives and places along the Swat River. A Swiss-supported assessment of the 2022 event describes erosion, sediment and the use of the river corridor as connected issues.</p><p>A 2025 study also examines changing land cover and the interaction of floods, debris flows and settlements. These findings ask us to see the entire catchment, rather than a river as a narrow line.</p>${read(source.environment,'Read the 2025 research')}<div class="environment-diagram"><span class="eyebrow">A conceptual cross-section</span><svg viewBox="0 0 600 170" role="img" aria-label="Conceptual river corridor showing channel and surrounding flood space"><path d="M0 30 L80 75 L140 105 L220 105 L250 145 L335 145 L365 105 L470 105 L530 60 L600 30" fill="none" stroke="#cad7b0" stroke-width="2"/><path d="M245 130 L340 130 L335 145 L250 145Z" fill="#b8d1b9"/><path d="M140 95H470" stroke="#c9b78a" stroke-dasharray="4 5"/><text x="258" y="168" fill="#cad7b0" font-size="11">River channel</text><text x="225" y="65" fill="#cad7b0" font-size="11">The wider river corridor</text></svg><p>A conceptual illustration, not measured flood extents or a prediction. A river’s influence extends beyond the water visible on a quiet day.</p></div><p>Looking after a place begins with attention: to river space, forest cover, local knowledge and the consequences of where we build.</p>${read(source.flood,'Read the Swat flood assessment')}</div></section>`}
function place(id){const p=places.find(p=>p.id===id)||sidePlaces[id];if(!p)return `<div class="page-title"><h1>Place not found.</h1>${round('#/atlas','Return to the atlas')}</div>`;return `${p.image?`<section class="place-hero">${photo(p.image)}<div class="page-title"><a class="back" href="#/atlas">← THE RIVER ATLAS</a><h1>${p.name}</h1><p class="deck">${p.region}</p></div></section>`:`<div class="page-title"><a class="back" href="#/atlas">← THE RIVER ATLAS</a><h1>${p.name}</h1><p class="deck">${p.region}</p></div>`}<section class="essay"><span class="eyebrow">Place notes / ${p.name}</span><div><h2>A closer look.</h2><p>${p.land}</p><div class="language-row"><h3>Language</h3><p>${p.voice}</p></div><div class="language-row"><h3>Memory</h3><p>${p.memory}</p></div><p class="caption">${p.image?'The photograph depicts '+(p.image==='mahodand'?'Mahodand Lake':'Kalam Valley')+'. See the image credits for date and license.':'This place is represented through text and the schematic atlas; no photograph from another location is substituted.'}</p>${read(id==='barikot'?source.heritage:source.geo,'Sources for further reading')}<p>${round('#/atlas','Continue along the river')}</p></div></section>`}
function sources(){return `<div class="page-title"><span class="eyebrow">A transparent field guide</span><h1>Sources &<br>acknowledgements.</h1><p class="deck">Real places, credited photographs, and a distinction between what is documented and what is interpreted.</p></div><div class="credits"><h2>Photography</h2><p>All photographs are real images of Swat. They are resized, cropped and, in the hero, darkened for text contrast; no scenery has been generated or composited. Adapted image presentations remain under their respective CC BY-SA licenses.</p>${photos.map(p=>`<article><strong>${p.title}</strong><br>Photograph: ${p.author} · ${p.date}<br><a href="https://commons.wikimedia.org/wiki/File:${encodeURIComponent(p.title.replaceAll(' ','_'))}" target="_blank" rel="noopener">Original file & provenance</a> · <a href="https://creativecommons.org/licenses/by-sa/${p.license}/" target="_blank" rel="noopener">CC BY-SA ${p.license}</a></article>`).join('')}<h2>Reading the valley</h2>${[['Geography',source.geo,'Swat Valley: geographical and cultural overview.'],['River',source.river,'Swat River: river system and confluence context.'],['Archaeology',source.heritage,'UNESCO Tentative List: Bazira–Barikot. Tentative listing is distinguished from inscription.'],['Language & community',source.voices,'Zubair Torwali, Smithsonian Center for Folklife and Cultural Heritage: Torwali language, music and poetry.'],['Craft & collections',source.craft,'The provincial archaeology directorate documents local embroidery, carved wood and jewellery in Swat Museum.'],['Gawri',source.gawri,'Gawri language overview and linguistic bibliography.'],['Environment',source.environment,'Natural Hazards and Earth System Sciences, 2025: dynamics and impacts of the 2022 Swat floods.'],['Flood assessment',source.flood,'Swiss Agency for Development and Cooperation: Swat Valley flood synthesis report.']].map(([title,url,note])=>`<article><strong>${title}</strong><p>${note}</p>${read(url)}</article>`).join('')}<h2>About this experience</h2><article>An independent browser prototype, researched October 2026. It is not an official tourism service, a live conditions report, or a navigational map. The river atlas is deliberately schematic; its spacing is not proportional to distance. Language notes describe broad associations, not exclusive boundaries.</article><article>Typography: Italiana by Santiago Orozco and DM Sans by Colophon Foundry, available through Google Fonts under the SIL Open Font License. The Arabic-script language names identify languages; this prototype does not claim to provide a translated interface.</article></div>`}
function render(){const route=location.hash.slice(2)||'';const [page,id]=route.split('/');const views={atlas,heritage,voices,changing,sources};$('#main').innerHTML=page==='place'?place(id):(views[page]||home)();document.title=(page?`${page==='place'?(places.find(p=>p.id===id)||sidePlaces[id])?.name||'Place':({atlas:'The river atlas',heritage:'Deep time',voices:'A valley of voices',changing:'A changing landscape',sources:'Sources & photography'})[page]} — `:'')+'SWAT';$('#menu').hidden=true;$('#menu-button').setAttribute('aria-expanded','false');window.scrollTo(0,0);if(page==='atlas'){updateAtlas();document.querySelectorAll('[data-place]').forEach(el=>{const choose=()=>{selected=+el.dataset.place;updateAtlas()};el.addEventListener('click',choose);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose()}})});document.querySelectorAll('[data-lens]').forEach(b=>b.onclick=()=>{lens=b.dataset.lens;updateAtlas()});$('.atlas-controls input').oninput=e=>{selected=+e.target.value;updateAtlas()};$('#upstream').onclick=()=>{selected=Math.max(0,selected-1);updateAtlas()};$('#downstream').onclick=()=>{selected=Math.min(5,selected+1);updateAtlas()}}document.querySelectorAll('.layer-toggle').forEach(b=>b.onclick=()=>{const open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',!open);$('#'+b.getAttribute('aria-controls')).hidden=open;b.querySelector('span').textContent=open?'+':'−'});}
$('#menu-button').onclick=()=>{const open=$('#menu').hidden;$('#menu').hidden=!open;$('#menu-button').setAttribute('aria-expanded',open)};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#menu').hidden=true;$('#menu-button').setAttribute('aria-expanded','false');$('#menu-button').focus()}});window.addEventListener('hashchange',()=>{render();$('#main').focus({preventScroll:true})});render();
